#!/usr/bin/env python3
"""Offline generate exact Rust stdlib Unicode predicates and uppercase mapping."""
import hashlib
import subprocess
from pathlib import Path

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
binary=ROOT/'work/_releasemeta-rust-reference/unicode'
binary.parent.mkdir(parents=True,exist_ok=True)
subprocess.run(['rustc','--edition=2024',str(HERE/'unicode.rs'),'-o',str(binary)],check=True)
rows=subprocess.check_output([str(binary)],text=True).splitlines()
version=rows.pop(0).split('\t')[1]
sets=[[],[],[]]
upper={}
lower={}
for line in rows:
    value,flag,casing,lowercase=line.split('\t')
    value=int(value,16)
    flag=int(flag)
    for index in range(3):
        if flag & (1<<index):sets[index].append(value)
    casing=[int(x,16) for x in casing.split(',')]
    if casing != [value]:upper[value]=''.join(chr(x) for x in casing)
    lowercase=[int(x,16) for x in lowercase.split(',')]
    if lowercase != [value]:lower[value]=''.join(chr(x) for x in lowercase)
text='''// Code generated by testdata/plugins/releasemeta-rust-reference/generate_unicode.py.
// Offline data only; the runtime is pure Go. Rust Unicode version: VERSION.
// Rust stdlib uses Unicode data; see https://www.unicode.org/license.txt.
package rustanime

import "sort"

type sourceUnicodeRange struct { lo,hi rune }
func sourceRuneIn(r rune, table []sourceUnicodeRange) bool {
 i:=sort.Search(len(table),func(i int)bool{return table[i].hi>=r})
 return i<len(table)&&table[i].lo<=r
}
func sourceAlphabetic(r rune)bool{return sourceRuneIn(r,sourceAlphabeticRanges)}
func sourceNumeric(r rune)bool{return sourceRuneIn(r,sourceNumericRanges)}
func sourceUppercase(r rune)bool{return sourceRuneIn(r,sourceUppercaseRanges)}

'''.replace('VERSION',version)
for name,values in zip(['Alphabetic','Numeric','Uppercase'],sets):
    ranges=[]
    for value in values:
        if ranges and ranges[-1][1]+1==value:ranges[-1][1]=value
        else:ranges.append([value,value])
    text+='var source'+name+'Ranges=[]sourceUnicodeRange{\n'
    text+=''.join('{0x%x,0x%x},\n'%tuple(r) for r in ranges)+'}\n'
text+='var sourceUpperMappings=map[rune]string{\n'
for r,value in upper.items():
    escaped=''.join('\\U%08x'%ord(c) for c in value)
    text+='0x%x:"%s",\n'%(r,escaped)
text+='}\n'
text+='var sourceLowerMappings=map[rune]string{\n'
for r,value in lower.items():
    escaped=''.join('\\U%08x'%ord(c) for c in value)
    text+='0x%x:"%s",\n'%(r,escaped)
text+='}\n'
path=ROOT/'internal/releasemeta/rustanime/unicode_data.go'
path.write_text(text)
print(dict(unicode=version,flags=[len(x) for x in sets],upper=len(upper),sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
